import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    D = int(data[0])
    G = int(data[1])

    p = [0] * (D + 1)
    c = [0] * (D + 1)

    index = 2
    for i in range(1, D + 1):
        p[i] = int(data[index])
        c[i] = int(data[index + 1])
        index += 2

    dp = [[float('inf')] * (G + 1) for _ in range(D + 1)]
    dp[0][0] = 0

    for i in range(1, D + 1):
        for j in range(G + 1):
            dp[i][j] = dp[i - 1][j]
            for k in range(p[i] + 1):
                score = 100 * i * k
                if score + c[i] <= j:
                    dp[i][j] = min(dp[i][j], dp[i - 1][j - score - c[i]] + k + 1)
                else:
                    dp[i][j] = min(dp[i][j], dp[i - 1][j - score] + k)

    result = float('inf')
    for j in range(G, G + 100):
        result = min(result, dp[D][j])

    print(result)

